function changeTemper(delta){changeVitals(S,{temper:delta});}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function plog(text){S.log.unshift({time:fmt(S.clock),text});S.log=S.log.slice(0,12);$('logList').innerHTML=S.log.slice(0,5).map(e=>`<div class="log-entry"><time>${e.time}</time>${esc(e.text)}</div>`).join('');}
function beep(){if(!S.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();for(let i=0;i<2;i++){const o=audio.createOscillator(),g=audio.createGain(),start=audio.currentTime+i*.24;o.type='sine';o.frequency.setValueAtTime(i?740:610,start);g.gain.setValueAtTime(0,start);g.gain.linearRampToValueAtTime(.055,start+.02);g.gain.linearRampToValueAtTime(0,start+.15);o.connect(g);g.connect(audio.destination);o.start(start);o.stop(start+.16);}}catch{}}
function characterExpression(kind=S.mode){return expression({clock:S.clock,energy:S.energy,temper:S.temper,mode:kind,caseId:phase().case,urgent:!!CASES[phase().case]?.urgent,food:['break','social'].includes(phase().kind)});}
function illustration(kind){const index=sceneIndex(S.location,{sleep:kind==='sleep',dawn:kind==='end'});return`<aside class="illustration-pane" aria-hidden="true"><div class="scene-art">${sceneSVG(index)}</div><div class="story-portrait portrait-avatar" style="${portraitStyle(characterExpression(kind))}"></div><div class="story-character"><b>${esc(S.name)}</b><span>ENT R / ${S.location==='f5'?'刀房工作中':S.clock>=1440&&S.clock<1800?'夜間值班':'耳鼻喉科住院醫師'}</span></div></aside>`;}
function modal(html,{kind='story',wide=false,dismissible=true,onClose=null}={}){lastFocus=document.activeElement;modalOptions={dismissible,onClose};S.mode=kind;world?.stop();keys.clear();const illustrated=['story','case','call','sleep','end'].includes(kind);$('modalCard').classList.toggle('wide',wide);$('modalCard').classList.toggle('illustrated',illustrated);$('modalCard').classList.toggle('welcome-card',kind==='welcome');$('modalCard').dataset.kind=kind;$('modalContent').innerHTML=illustrated?`${illustration(kind)}<div class="story-pane">${html}</div>`:html;$('modal').hidden=false;$('modalCard').scrollTop=0;$('callBanner').hidden=true;const close=$('closeModal');if(close)close.onclick=closeModal;requestAnimationFrame(()=>{const focus=[...$('modalContent').querySelectorAll('input,select,button:not([disabled])')].find(el=>el.getClientRects().length);focus?.focus({preventScroll:true});});}
function closeModal(){const onClose=modalOptions.onClose;modalOptions.onClose=null;if(onClose){onClose();return;}if(S.mode==='sleep')restTimer=0;S.mode='walk';$('modal').hidden=true;keys.clear();lastFocus?.focus?.({preventScroll:true});renderHUD();}
function topLine(label,close=true){return`<div class="modal-topline"><span>${esc(label)}</span>${close?'<button class="modal-close" id="closeModal" aria-label="關閉">×</button>':''}</div>`;}
function choiceList(options){return`<div class="choice-list">${options.map((o,i)=>`<button class="choice-button" data-choice="${i}"><span>${String(i+1).padStart(2,'0')}</span><span>${esc(o.text)}</span><span class="choice-arrow">→</span></button>`).join('')}</div>`;}
function bindChoices(handler){$('modalContent').querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>handler(Number(b.dataset.choice)));}
function reply(title,text,callback,button='繼續'){modal(`${topLine('值班日誌',false)}<span class="modal-tag">現場回應</span><h2 id="modalTitle">${esc(title)}</h2><div class="dialogue">${lines(text)}</div><button id="replyContinue" class="primary-button">${esc(button)} <span>→</span></button>`,{dismissible:false});$('replyContinue').onclick=callback;}

function showMorningCalendar(view={}){
  const o=S.opening;if(!o)return;const today=o.today.split('-').map(Number),year=view.year??today[0],month=view.month??today[1]-1,selected=view.selected??null;
  modal(`${topLine('ENT 科內行事曆')}${calendarHTML(o,{year,month,selected,nowLabel:fmt(S.clock)})}`,{kind:'calendar',wide:true});
  const move=delta=>{const d=new Date(Date.UTC(year,month+delta,1));showMorningCalendar({year:d.getUTCFullYear(),month:d.getUTCMonth()});};
  $('calendarPrev').onclick=()=>move(-1);$('calendarNext').onclick=()=>move(1);$('calendarToday').onclick=()=>showMorningCalendar();
  document.querySelectorAll('[data-calendar-date]').forEach(b=>b.onclick=()=>{if(b.dataset.calendarDate===o.today)checkMorningCalendar(o);showMorningCalendar({year,month,selected:b.dataset.calendarDate});renderHUD();});
  if($('calendarContinue'))$('calendarContinue').onclick=()=>{o.focused=o.conference&&!['done','missed'].includes(o.stage);closeModal();renderHUD();guide();};
  $('calendarClose').onclick=closeModal;
}
function renderOpeningHUD(){const o=S.opening;if(!openingTarget(o))return;const known=o.checked,t=conferenceType(o),late=o.attendance==='late';
  $('missionIndex').textContent=known?'07:30 / '+t.label:'07:20 / 開始今天的工作';$('missionTitle').textContent=known?(late?'晨會遲到了，先進討論室':S.clock<450?'07:30 晨會，記得準時到場':'晨會開始了，輪到你報 paper'):'確認今日有無晨會';$('missionDescription').textContent=known?'今天報告：'+conferencePaper(o).title+'。到討論室前方的電腦開始；遲到與缺席都會接到主治電話。':'你坐在護理站。點上方行事曆，再點「今天」，確認要先參加晨會或直接查房。';$('missionDestination').textContent=known?'7F 討論室 · 07:30 開始':'行事曆 · 點選今天查看';$('guideButton').innerHTML=known?'前往討論室 →':'打開行事曆 ▦';$('phaseContinue').hidden=true;
}
function conferenceClock(){
  if(!S.opening||!callTimeRunning(S))return;
  const notices=tickConference(S.opening,S.clock,{present:inDiscussionRoom(S.location,world.position)});
  for(const reason of notices){if(reason==='missed')removeCall('conference-late');queueCall(conferenceCall(S.opening,reason));plog(reason==='missed'?'晨會缺席紀錄已保留，病房工作繼續。':'晨會遲到紀錄已保留。');}
}
function answerConferencePhone(call){
  if(!['walk','sleep'].includes(S.mode))return;const o=S.opening;if(!o)return;const missed=call.reason==='missed'||o.stage==='missed';S.answeringCallId=call.id;
  const text=missed?'今天7:30的'+conferenceType(o).label+'，你的 paper 呢？整場都沒等到人。行事曆不是放著好看的，下次準時到！病房的事情也要接好。':o.attendance==='late'?'晨會7:30就開始了，你剛剛幾點才進來？是7:30開始，不是7:30才從護理站出發。先把 paper 報完！':'晨會7:30開始，大家都坐好了，你人在哪？paper還在等你，不要每次都讓整間討論室等！';
  modal(`${topLine(call.source)}<span class="modal-tag">☎ ${missed?'晨會缺席':'晨會遲到'} · 脾氣 +${call.penalty}</span><h2 id="modalTitle">${missed?'晨會你去哪了？':'晨會已經開始了！'}</h2><div class="dialogue">${esc(o.attending)}主治：「${esc(text)}」</div><button id="conferenceCallReply" class="primary-button">${missed?'收到，接著把病房工作做好':'收到，立刻去討論室'} →</button>`,{kind:'call'});
  $('conferenceCallReply').onclick=()=>{removeCall(call.id);if(!o.acknowledged.includes(call.reason))o.acknowledged.push(call.reason);o.focused=!missed&&o.stage!=='done';closeModal();renderHUD();if(o.focused)guide();};
}
function showConference(){
  const o=S.opening;if(!o){reply('7F 討論室','這裡是晨會報 paper 的地方，今天的安排可以在行事曆查看。',closeModal);return;}
  conferenceClock();if(!o.checked){showMorningCalendar();return;}
  if(!o.conference||['done','missed'].includes(o.stage)){reply('討論室',o.stage==='missed'?'晨會已結束，缺席紀錄與主治來電仍會保留。接著完成病房工作。':o.conference?'今日 paper 已報告完成。接著去印名單查房。':'今天沒有晨會，可以直接印名單查房。',closeModal);return;}
  o.focused=true;
  if(S.clock<CONFERENCE_START){modal(`${topLine('7F 討論室')}<span class="modal-tag">${esc(conferenceType(o).label)} · 07:30 開始</span><h2 id="modalTitle">提早到了，先準備 paper。</h2><p class="modal-copy">今天報告：${esc(conferencePaper(o).title)}<br>人已在討論室，等07:30開始。</p><button id="conferenceWait" class="primary-button">在討論室準時等到 07:30 →</button><button id="conferenceLater" class="text-button">先離開，記得07:30前回來</button>`,{kind:'conference'});$('conferenceWait').onclick=()=>{S.clock=CONFERENCE_START;conferenceClock();showConference();};
  }else if(o.stage==='report'||o.stage==='waiting'){
    modal(`${topLine('7F 討論室 · paper 報告')}${paperHeading(o)}<div class="dialogue">${esc(o.attending)}主治：「好，今天這篇，你報給大家聽。」<br><br>三頁簡短報告，結束後回答兩個問題。</div><button id="conferenceReport" class="primary-button">開始報 paper →</button><button id="conferenceLater" class="text-button">先離開，稍後繼續</button>`,{kind:'conference',wide:true});$('conferenceReport').onclick=()=>{conferenceClock();if(beginConference(o,S.clock)){plog('晨會報告：'+conferencePaper(o).title);showConference();}};
  }else if(o.stage==='slides'){
    modal(`${topLine('7F 討論室 · paper reading')}${paperSlideHTML(o)}`,{kind:'conference',wide:true});$('paperPrevious').onclick=()=>{if(o.slide>0)o.slide--;showConference();};$('paperNext').onclick=()=>{nextConferenceSlide(o);spendShiftTime(S,.5);showConference();};
  }else{
    const qs=conferenceQuestions(o),q=qs[o.question];modal(`${topLine('7F 討論室 · 主治提問')}<span class="modal-tag">${o.question+1} / ${qs.length} · 科內虛構 paper</span><h2 id="modalTitle">${esc(q.question)}</h2><p class="paper-question-title">${esc(conferencePaper(o).title)}</p>${choiceList(q.options)}<button id="conferenceLater" class="text-button">先離開，報告進度保留</button>`,{kind:'conference'});
    bindChoices(i=>{if(!answerConference(o,i)){changeTemper(VITAL_RULES.mistake);reply('主治：「再想一下。」',q.explanation,showConference,'重新回答');return;}spendShiftTime(S,.5);if(o.stage==='done'){plog('paper報告完成，接著查房。');reply('主治：「好，今天先到這裡。」','paper報完了。接著回護理站列印 patient list，再依名單查房。'+(o.attendance==='late'?'遲到紀錄仍會保留，該接的主治電話還是要接。':''),()=>{closeModal();renderHUD();guide();},'接續病房工作');}else showConference();});
  }
  if($('conferenceLater'))$('conferenceLater').onclick=closeModal;
}
function seatAtNursingStation(){world.teleportToSpot('rest-chair');beginWorldRest(world.spots.find(s=>s.id==='rest-chair'));}
function launchOpeningPreview({conference=true,paperId,clock=MORNING_START,atConference=false}={}){
  studioUseState(createStudioEvent('rounds',studioSeed,studioProfile()));S.clock=clock;S.run.concurrentPreview=true;S.morning.escort='waiting';S.opening=createMorningOpening(studioSeed,{conference,paperId});
  if(atConference){checkMorningCalendar(S.opening);S.opening.wasPresent=true;S.opening.presentSince=449;world.teleportToSpot('conference');conferenceClock();showConference();}else{seatAtNursingStation();toast('07:20，先確認今日有無晨會。點行事曆，再點今天查看。');}
}

