function selectMorning(focus){if(S.opening)S.opening.focused=false;S.food.focus=null;S.food.drinkSeeking=false;const m=S.morning;if(!m?.active)return;if(focus==='nasal'&&m.escort==='waiting'&&!roundsComplete(m)){m.focus='rounds';reply('先把整份名單查完','全部病床查房完成後，再回到 SMP 術後病人床邊，帶到檢查室清鼻子。',showPatientList,'查看 patient list');syncMorning();return;}m.focus=focus;closeModal();syncMorning();}
