function workHint(p){
  if(NIGHT_WARD_IDS.includes(p.case)){const t=S.wardCalls[p.id];return p.case==='wardConsent'?(t?consentStageText(t):'7F 護理站 · 平板簽名'):'任意電腦 · '+(t?t.patient.bed+' '+t.patient.name+' · '+t.item:'處理病房請託');}
  if(p.case==='orassist')return '13房 · '+(S.npx?NPX_TITLES[S.npx.stage]:'向流動拿刀單');
  if(LOCAL_OR_IDS.includes(p.case)){const t=S.localOR[CASES[p.case].localProcedure];return '13房 · '+(t?localTitle(t):'核對病人，再接續這台');}
  if(p.work.caseMode==='or'||p.case==='orSenior')return '16房 · '+(p.work.caseMode==='or'?'手術台協助操作':'接上學長的工作');
  const t=S.tubes[p.case];if(t)return '2G · '+tubeStageText(t);
  if(p.case==='fish'&&S.fish)return '2G · '+fishStageText(S.fish);
  if(p.case==='ng'&&S.wardNG)return '2G · '+ngStageText(S.wardNG);
  if(p.case==='sudden'&&S.hearingConsult)return '2G · '+consultStageText(S.hearingConsult);
  return (LOCATIONS[p.work.activeDest||p.dest]?.code||'現場')+' · '+(p.work.caseStep?'第 '+(p.work.caseStep+1)+' 步':'前往處理');
}
function pendingCard({title,meta,status,icon='＋',attrs='',kind='work',active=false}){return `<button class="pending-item task-${kind} ${active?'selected-work':''}" ${attrs}><span class="pending-icon">${icon}</span><div><span class="pending-status">${esc(status)}</span><strong>${esc(title)}</strong><small>${esc(meta)}</small></div><span class="arrow">→</span></button>`;}
function renderPending(){
  const m=S.morning,groups=[];let count=0;
  const group=(title,rows)=>{if(!rows.length)return;count+=rows.length;groups.push(`<div class="pending-group-title">${title}<span>${rows.length}</span></div>`+rows.join(''));};
  group('待接來電',calls.map(c=>pendingCard({title:c.title,meta:c.source+(c.receivedAt!==undefined?' · '+fmt(c.receivedAt):''),status:c.urgent?'緊急來電':'來電待接',icon:'☎',kind:c.urgent?'urgent':'call',attrs:`data-call="${esc(c.id)}"`})));
  const work=parallelCalls(S)?pendingWork(S):S.accepted&&phase().kind==='case'?[{...phase(),index:S.phase,work:{activeDest:S.activeDest,caseMode:S.caseMode,caseStep:S.caseStep}}]:[];
  work.sort((a,b)=>Number(b.index===S.phase)-Number(a.index===S.phase)||Number(!!CASES[b.case].urgent)-Number(!!CASES[a.case].urgent)||a.clock-b.clock);
  group('已接工作 · 點選切換',work.map(p=>pendingCard({title:NIGHT_WARD_IDS.includes(p.case)&&p.case!=='wardConsent'?(S.wardCalls[p.id]?.item||CASES[p.case].title):CASES[p.case].title,meta:workHint(p),status:p.index===S.phase?'正在處理':CASES[p.case].urgent?'緊急 · 待處理':'待處理 · 進度保留',icon:p.index===S.phase?'▶':'＋',kind:CASES[p.case].urgent?'urgent':'work',active:p.index===S.phase,attrs:`data-work="${p.index}" aria-pressed="${p.index===S.phase}"`})));
  const ward=[];if(m&&!m.printed&&(!S.opening||S.opening.checked))ward.push(pendingCard({title:'列印 patient list，開始查房',meta:'7F 護理站 · 電腦',status:'早晨待辦',icon:'☷',attrs:'id="printListTask"'}));if(S.opening&&!['done','missed'].includes(S.opening.stage))ward.push(pendingCard({title:S.opening.checked?conferenceType(S.opening).label+' · paper報告':'確認今日有無晨會',meta:S.opening.checked?'7F 討論室 · 07:30準時開始':'點月曆中的今天查看',status:'早晨待辦',icon:'▦',attrs:'id="openingTask"'}));
  if(m?.active){if(!S.completed.includes('rounds'))ward.push(pendingCard({title:'查房 patient list',meta:m.visited.length+' / '+m.list.length+' 床已完成',status:'病房待辦',icon:'☷',attrs:'id="roundsTask"'}));if(m.escort!=='done')ward.push(pendingCard({title:'鼻術後病人清鼻子',meta:m.escort==='waiting'?bedLabel(m.list.find(p=>p.nasal))+(roundsComplete(m)?' · 待接病人':' · 查完房再接'):m.escort==='following'?'帶病人到檢查室':'檢查室 · 已清 '+m.cleaned.length+' / 3',status:'病房待辦',attrs:'id="nasalPending"'}));}
  if(S.awaitingDesk)ward.push(pendingCard({title:'回初診間等病房會診',meta:'2G · 電腦旁坐下等候',status:'待處理',icon:'☎',attrs:'id="clinicTask"'}));
  if(parallelCalls(S)&&S.clock>=1890)ward.push(pendingCard({title:'07:30 回護理站交班',meta:'未完成工作會列入交班成績',status:'準備交班',icon:'✓',attrs:'id="shiftHandover"'}));group('病房與交班',ward);
  const food=[];for(const o of pendingFood(S.food)){const ready=foodStatus(o,S.clock)==='ready';food.push(pendingCard({title:o.name,meta:pickupLabel(o)+' · '+(ready?'領取並享用':o.awaitingExit?'出房後可領取':fmt(o.readyAt)+' 送達'),status:ready?'可以領取':'已訂 · 等候送達',icon:'◒',kind:'food',attrs:`data-food-pickup="${o.id}" ${ready?'':'disabled'}`}));}
  if(S.food.drinkOffered&&!S.food.drinkResponded)food.push(pendingCard({title:'回覆流動：要不要訂飲料？',meta:'回刀房找流動',status:'餐飲待辦',icon:'◒',attrs:'id="orDrinkTask"'}));
  if(focusedFood(S.food,S.clock)||S.food.drinkSeeking)food.push(pendingCard({title:'回到原本工作',meta:'餐飲待辦保留',status:'繼續工作',icon:'↩',attrs:'id="resumeWork"'}));group('餐點與飲料',food);
  const html=groups.join('')||'<div class="empty-pending"><span>✓</span><p>目前沒有待辦<br>趁空檔吃一口、坐一下。</p></div>';
  if($('pendingList').innerHTML!==html){$('pendingList').innerHTML=html;
    $('pendingList').querySelectorAll('[data-call]').forEach(b=>b.onclick=()=>answerCall(b.dataset.call));
    $('pendingList').querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>{if(S.mode!=='walk')return;if(parallelCalls(S))selectWork(S,Number(b.dataset.work));buildMarkers();S.clinicCallDeferred=false;if(m?.active)m.focus='call';renderHUD();guide();});
    if($('printListTask'))$('printListTask').onclick=()=>{S.opening&&(S.opening.focused=false);closeModal();guide();};if($('openingTask'))$('openingTask').onclick=()=>{if(!S.opening.checked){showMorningCalendar();return;}S.opening.focused=true;if(S.morning?.printed)S.morning.focus='call';closeModal();guide();};
    if($('roundsTask'))$('roundsTask').onclick=showPatientList;if($('nasalPending'))$('nasalPending').onclick=()=>{selectMorning('nasal');guide();};if($('clinicTask'))$('clinicTask').onclick=()=>{S.food.focus=null;S.food.drinkSeeking=false;if(m?.printed)m.focus='call';guide();};
    if($('shiftHandover'))$('shiftHandover').onclick=()=>{if(S.mode!=='walk')return;selectWork(S,S.run.phases.findIndex(p=>p.kind==='finish'));if(m?.active)m.focus='call';renderHUD();guide();};
    $('pendingList').querySelectorAll('[data-food-pickup]').forEach(b=>b.onclick=()=>{if(focusFood(S.food,b.dataset.foodPickup,S.clock)){renderHUD();guide();}});
    if($('orDrinkTask'))$('orDrinkTask').onclick=()=>{S.food.focus=null;S.food.drinkSeeking=true;renderHUD();guide();};if($('resumeWork'))$('resumeWork').onclick=()=>{S.food.focus=null;S.food.drinkSeeking=false;renderHUD();};
  }
  $('pendingCount').textContent=count+' 件';renderCallNotice();const first=calls[0];$('callBanner').hidden=!first||!S.started||S.mode!=='walk';if(first){$('callTitle').textContent=first.title;$('callSource').textContent=first.source;}
}
function renderVitalHUD(){for(const item of hudVitals(S)){const meter=$(item.key+'Meter');meter.dataset.level=item.level;$(item.key+'Hint').textContent=item.hint;const track=meter.querySelector('[role="progressbar"]');track.setAttribute('aria-valuenow',item.value);track.setAttribute('aria-valuetext',item.label+' '+item.value+' / 100，'+item.hint);}}
function renderCallNotice(){
  let el=$('incomingNotice');if(!el){el=document.createElement('div');el.id='incomingNotice';el.className='incoming-notice';el.setAttribute('role','status');el.setAttribute('aria-live','polite');document.body.append(el);}
  const pending=calls.filter(c=>S.mode!=='call'||c.id!==S.answeringCallId);
  el.hidden=!S.started||!pending.length||['walk','welcome','pause','help','studio','end'].includes(S.mode);
  const message=pending.length?'☎ '+pending.length+' 通待接 · '+pending[0].title+'（完成或離開目前畫面後接聽）':'';if(el.textContent!==message)el.textContent=message;
}
function dispatchCalls(){
  if(!parallelCalls(S))return;
  const due=releaseDueCalls(S);if(due.length&&S.care.posture==='lie'){endRest(S,{force:true});world.setPosture('stand');S.stats.woken++;plog('你剛躺下不久，電話又響了。');}
  for(const p of due){const c=CASES[p.case];queueCall({id:p.id,kind:'case',caseId:p.case,title:c.title,source:c.source,urgent:c.urgent});}
  if(S.mode==='walk'&&!S.accepted&&!phase().case){const index=idlePhase(S);if(index!==S.phase)selectWork(S,index);}
}
function queueCall(call){if(calls.some(c=>c.id===call.id))return;call.receivedAt??=S.clock;if(NIGHT_WARD_IDS.includes(call.caseId)){const task=ensureWardCall(call.id);call.title=call.caseId==='wardConsent'?'同意書待簽 · '+task.patient.bed:task.item;call.source='7F 病房 · '+task.patient.bed+' '+task.patient.name;}if(TUBE_CASES.includes(call.caseId))S.clinicNurseAway=true;if(call.caseId==='ng')call.source=ngSource(ensureNG());if(call.caseId==='sudden'&&!call.audiology)call.source=consultSource(ensureConsult());if(call.caseId==='contact')call.source=ensureContact().caller;calls.push(call);const temper=call.penalty??(call.urgent?VITAL_RULES.urgentCall:VITAL_RULES.call);changeTemper(temper);calls.sort((a,b)=>Number(!!b.urgent)-Number(!!a.urgent)||Number(a.kind==='food')-Number(b.kind==='food'));beep();plog(`${call.source}來電：${call.title} · 脾氣 +${temper}`);renderHUD();}
function removeCall(id){calls=calls.filter(c=>c.id!==id);}
function schedule(fn,delay=1800){callTimers.push({state:S,fn,remaining:delay/1000});}

function enterPhase(index,{immediate=false}={}){if(parallelCalls(S)){selectWork(S,index);dispatchCalls();renderHUD();return;}phaseToken++;S.nightWaitElapsed=0;S.food.focus=null;S.food.drinkSeeking=false;S.phase=Math.min(index,S.run.phases.length-1);S.accepted=false;S.clinicCallDeferred=false;S.activeDest=null;S.caseStep=0;S.caseMode='patient';calls=[];const p=phase();S.clock=Math.max(S.clock,p.clock);S.awaitingDesk=!!(p.kind==='case'&&CASES[p.case].requiresDesk);if(p.kind==='case'&&!S.awaitingDesk){const c=CASES[p.case];const call={id:p.case,kind:'case',caseId:p.case,title:c.title,source:c.source,urgent:c.urgent};if(immediate)queueCall(call);else schedule(()=>queueCall(call));}else if(p.kind==='sleep')plog('午夜了。可以回 7F 病房後方的值班室。');renderHUD();}
function advance(){if(parallelCalls(S)){const p=phase();saveWork(S);if(!p.case)dispatchState(S).handled.push(p.id);if(S.morning?.printed)S.morning.focus=p.id==='morning'?'rounds':'call';closeModal();const next=pendingWork(S)[0];selectWork(S,next?.index??idlePhase(S));buildMarkers();dispatchCalls();renderHUD();return;}if(S.run?.studio&&S.completed.includes(S.run.testId)){showStudioResult();return;}S.care.nightRest=false;S.care.nightElapsed=0;if(S.morning?.printed&&S.run.phases[S.phase+1]?.kind!=='morning-work')S.morning.focus='call';closeModal();enterPhase(S.phase+1);}
function guide(){if(!S.started||S.mode!=='walk')return;if(S.opening?.focused&&!S.opening.checked){showMorningCalendar();return;}if(!standForWork())return;if(!focusedFood(S.food,S.clock)&&!S.food.drinkSeeking&&S.morning?.active&&S.morning.focus==='rounds'&&S.morning.visited.length===S.morning.list.length){showPatientList();return;}if(!focusedFood(S.food,S.clock)&&!S.food.drinkSeeking&&isWaitingCall()){const c=calls.find(c=>c.kind!=='food');if(c)answerCall(c.id);else toast('電話就要響了，等一下。');return;}const goal=currentGoal(),spot=world.spots.find(s=>s.id===goal);if(!spot){toast('先打開院區動線，確認目的地。');return;}if(!world.walkToSpot(spot.id))toast('這邊有障礙物，試著換一條走道。');else toast(goal==='elevator'?'走到電梯後，按 E 選樓層。':goal==='bridge'?'走近連通區，再按 E 跨棟。':'走近後，按 E 互動。');}

function answerCall(id=calls[0]?.id){const call=calls.find(c=>c.id===id);if(call?.kind==='conference'){answerConferencePhone(call);return;}if(!call||call.kind!=='case')return;if(S.mode!=='walk'&&S.mode!=='sleep')return;if(S.mode==='sleep'){S.stats.woken++;S.stats.restSeconds+=restTimer;restTimer=0;plog('你剛躺下不久，電話就響了。');}
S.food.focus=null;S.food.drinkSeeking=false;if(S.opening)S.opening.focused=false;S.answeringCallId=id;
if(parallelCalls(S)){const index=S.run.phases.findIndex(p=>p.id===call.id||call.audiology&&p.case===call.caseId);if(index<0)return;selectWork(S,index);}
if(call.caseId==='fish'){openFishPhone(call);return;}
if(call.caseId==='ng'){openNGPhone(call);return;}
if(call.caseId==='sudden'){openConsultPhone(call);return;}
if(call.caseId==='booking'){openBookingPhone(call);return;}
if(call.caseId==='contact'){openContactPhone(call);return;}
const priorFocus=S.morning?.focus;if(S.morning?.active)S.morning.focus='call';
const c=NIGHT_WARD_IDS.includes(call.caseId)?ensureWardCall(phase().id):CASES[call.caseId],options=shuffledOptions(c.phone,'phone');
modal(`${topLine(c.source)}<span class="modal-tag ${c.urgent?'urgent':''}">☎ ${esc(c.tag)}</span><h2 id="modalTitle">${esc(c.title)}</h2><div class="dialogue"><small>電話那一端</small>${lines(c.call)}</div>${choiceList(options)}<button id="laterCall" class="secondary-button">保留來電，稍後回覆</button>`,{kind:'call'});
bindChoices(i=>{const option=options[i];if(option.why){recordMistake();reply('再把資訊問清楚',option.why,()=>{closeModal();answerCall(id);},'重新回覆');return;}
  const plan=c.outpatient?clinicPhonePlan(option.outpatientAction,S.morning):'clinic';
  removeCall(id);
  if(plan==='recall'){
    if(S.morning?.active)S.morning.focus=priorFocus;plog('掛掉診間電話；門診工作仍未回覆。');
    reply('嘟——你把電話掛了。','診間的工作還在，這通電話沒有算處理完成。\n\n分機等一下會再打來。',()=>{closeModal();schedule(()=>queueCall({...call}),2500);},'回到手邊工作');return;
  }
  if(c.phoneOnly){applyEffects(option.effect);finishCase(option.reply);return;}
  S.accepted=true;S.activeDest=option.dest;if(LOCAL_OR_IDS.includes(call.caseId))ensureORProcedure();S.clinicCallDeferred=plan==='rounds';if(S.clinicCallDeferred)S.morning.focus='rounds';
  if(TUBE_CASES.includes(call.caseId))ensureTubeTask(call.caseId);if(option.support){S.stats.support++;plog('已聯繫資深與相關團隊。');}
  plog(c.shortCall&&call.caseId!=='wardConsent'?'病房請託已記下：'+ensureWardCall().item+'，找任意電腦處理。':S.clinicCallDeferred?'診間病人先等候，查完房再下樓。':'事件安排：'+(option.dest==='f5'?operatingLabel(assignedOR()):LOCATIONS[option.dest].code+' '+LOCATIONS[option.dest].name));
  const text=S.clinicCallDeferred?option.reply+'\n\n先完成 patient list 上還沒查完的病床，查完後會接回這件門診工作。':option.reply+(option.outpatientAction==='finish-rounds'?'\n\n今天的查房已完成，可以前往初診間。':'')+(option.dest==='f5'?'\n請到 '+assignedOR()+' 號刀房。':'');
  reply('來電已回覆',text,()=>{closeModal();renderHUD();},S.clinicCallDeferred?'繼續查房':c.shortCall&&call.caseId!=='wardConsent'?'回電腦處理':'前往現場');
});$('laterCall').onclick=()=>{if(S.morning?.active)S.morning.focus=priorFocus;closeModal();};}

function nearAnyComputer(){return world?.spots.some(p=>isWardComputer(S.location,S.orRoom,p.id)&&nearWorkSpot(p.id,S.location,S.orRoom));}
function showOnlineRecords(){
  if(!nearAnyComputer())return;const records=onlineRecords(S,CASES);
  modal(`${topLine('電腦 · 院內系統')}<h2 id="modalTitle">病歷與影像</h2><p class="modal-copy">直接在電腦查看病歷、影像與檢查報告。</p><div class="choice-list">${records.map(r=>`<button class="choice-button" data-online-record="${esc(r.id)}"><span>▤</span><span>${esc(r.name)}<br><small>${esc(r.title)}</small></span><span>→</span></button>`).join('')||'<p class="modal-copy">目前沒有開啟的病人紀錄。</p>'}</div><button id="recordsClose" class="secondary-button">離開電腦</button>`,{kind:'records',wide:true});
  document.querySelectorAll('[data-online-record]').forEach(b=>b.onclick=()=>showOnlineRecord(b.dataset.onlineRecord));$('recordsClose').onclick=closeModal;
}
function showOnlineRecord(id,tab='chart'){
  if(!nearAnyComputer())return;const r=onlineRecords(S,CASES).find(r=>r.id===id);if(!r)return;
  const reportHTML=r.type==='consult'?consultReport(S.hearingConsult):r.type==='hearing'?audiogramSVG(S.hearing.patient):'';
  const fish=currentFish(),firstRead=id==='fish'&&fish?.stage==='history'&&!fish.recordReviewed;
  modal(`${topLine('電腦 · 線上病歷')}${onlineRecordHTML(r,{tab,reportHTML})}<div class="ehr-actions"><button id="onlineRecordDone" class="primary-button">${firstRead?'看完影像與病歷，到診療椅看病人':'看完，回到目前工作'} →</button><button id="onlineRecordList" class="secondary-button">病人紀錄列表</button></div>`,{kind:'records',wide:true});
  document.querySelectorAll('[data-record-tab]').forEach(b=>b.onclick=()=>showOnlineRecord(id,b.dataset.recordTab));$('onlineRecordList').onclick=showOnlineRecords;
  $('onlineRecordDone').onclick=()=>{if(!nearAnyComputer())return;if(firstRead&&fishAction(fish,'read-record').ok){plog('已在電腦查看 '+fish.patient.name+' 的線上病歷與lateral view。');walkToClinicSpot('patient');}else closeModal();};
}

function ensureFish(){return S.fish??=createFishCase((S.run?.seed||'ENT')+'|'+(S.run?.team||''));}
function currentFish(){return !S.explore&&S.accepted&&phase().case==='fish'&&S.fish&&!S.fish.finished?S.fish:null;}
function openFishPhone(call){
  const t=ensureFish();if(t.stage!=='phone')return;
  modal(`${topLine(FISH_EVENT.source)}<span class="modal-tag">☎ 急診會診</span><h2 id="modalTitle">ENT醫師，有一個 foreign body。</h2><div class="dialogue">NP：「${esc(FISH_EVENT.call)}」</div><button id="fishAskXray" class="choice-button" ${t.xrayAsked?'disabled':''}>${t.xrayAsked?'✓ 已問側面影像':'Lateral view 有看到東西嗎？'}</button>${t.xrayAsked?`<p class="fish-phone-answer">${esc(t.xray)}</p>`:''}<button id="fishSend" class="primary-button">請病人上來2G初診間 →</button><button id="fishPhoneLater" class="secondary-button">保留來電，稍後回覆</button>`,{kind:'call'});
  $('fishAskXray').onclick=()=>{fishAction(t,'xray');openFishPhone(call);};
  $('fishSend').onclick=()=>{if(!fishAction(t,'send').ok)return;removeCall(call?.id||'fish');S.accepted=true;S.activeDest='g2';if(S.morning?.active)S.morning.focus='call';plog('魚刺會診安排到2G；'+(t.xrayAsked?'已補問lateral view結果。':'直接請穩定病人上來，不扣分。'));reply('病人安排到初診間。','NP：「好，請'+t.patient.name+'上去。影像和病歷在電腦系統就看得到。」',()=>{closeModal();renderHUD();},'到2G電腦看影像');};
  $('fishPhoneLater').onclick=closeModal;
}
function renderFish(message=''){
  const t=currentFish();if(!t||!t.recordReviewed||!nearWorkSpot('patient','g2'))return;
  modal(`${topLine('2G 初診間 · 魚刺會診')}${fishHTML(t,message,shuffledOptions(FISH_PLANS,'fish-plan'))}`,{kind:'fish',wide:true});
  bindFish(t,{active:()=>currentFish()===t&&S.mode==='fish',later:closeModal,act:(action,value)=>{
    if(currentFish()!==t||S.mode!=='fish'||!nearWorkSpot('patient','g2'))return;
    const r=fishAction(t,action,value);if(!r.ok){if(r.penalty)recordMistake();$('fishFeedback').textContent=r.message;renderHUD();return;}
    if(r.completed){spendShiftTime(S,8);finishCase(r.message);return;}
    renderFish(r.message||'');renderHUD();
  }});
}
function renderFishHUD(){const t=currentFish();if(!t)return;$('missionIndex').textContent='急診會診 · 魚刺';$('missionTitle').textContent=fishStageText(t);$('missionDescription').textContent=t.patient.name+' · 已完成的檢查與取出進度會保留。';$('missionDestination').textContent='2G 初診間 · '+(fishSpot(t)==='desk'?'電腦':'診療椅');}

function ensureConsult(){return S.hearingConsult??=createHearingConsult((S.run?.seed||'ENT')+'|'+(S.run?.team||''));}
function currentConsult(){const t=S.hearingConsult;return t&&t.stage!=='done'&&(S.explore&&t.practice||!S.explore&&S.accepted&&phase().case==='sudden')?t:null;}
function ringAudiology(){if(!callTimeRunning(S))return;const call=consultResultsCall(S.hearingConsult,S.location);if(call)queueCall(call);}
function scheduleAudiology(task){schedule(()=>{if(S.hearingConsult!==task)return;if(consultAction(task,'audiology-ready')==='ready'){plog('聽力檢查完成；聽力室準備聯絡初診間。');ringAudiology();renderHUD();}},3500);}
function consultPracticeMenu(){modal(`${topLine('2G 工作桌 · 聽力會診練習')}<h2 id="modalTitle">先從一通病房電話開始。</h2><p class="modal-copy">隨機練習會等到檢查後才揭曉；也可以指定想練習的分支。不計分。</p><div class="choice-list"><button class="choice-button" data-consult-practice="random">隨機接一通病房會診 →</button><button class="choice-button" data-consult-practice="sshl">練習突發性聽損的問診與說明 →</button><button class="choice-button" data-consult-practice="wax">練習比對正常聽力圖與耳垢處理 →</button></div>`,{kind:'consult'});document.querySelectorAll('[data-consult-practice]').forEach(b=>b.onclick=()=>{S.booking=null;S.practiceTube=null;S.hearing=null;S.wardNG=null;S.contact=null;S.hearingConsult=createHearingConsult(S.run.seed+'|'+S.run.team,{practice:true,branch:b.dataset.consultPractice});openConsultPhone();});}
function openConsultPhone(call){
  const t=ensureConsult(),p=t.patient;
  if(call?.audiology){if(t.stage!=='results-ready')return;modal(`${topLine('聽力室 · 聽力師')}<span class="modal-tag">☎ 檢查完成通知</span><h2 id="modalTitle">病人做完了，在外面等。</h2><div class="dialogue">聽力師：「${esc(p.name)}的聽力檢查做完了，聽力圖已上傳系統，電腦可以看，病人在外面等你叫。」</div><button id="consultAcceptResults" class="primary-button">收到，回工作桌叫病人 →</button><button id="consultResultsLater" class="secondary-button">保留通知，稍後回覆</button>`,{kind:'call'});$('consultResultsLater').onclick=closeModal;$('consultAcceptResults').onclick=()=>{if(consultAction(t,'answer-results')!=='notified')return;removeCall(call.id);if(S.morning?.active)S.morning.focus='call';walkToClinicSpot('desk');};return;}
  if(t.stage!=='phone')return;if(t.priorFocus===undefined)t.priorFocus=S.morning?.focus||'call';if(S.morning?.active)S.morning.focus='call';
  modal(`${topLine(consultSource(t))}<span class="modal-tag">☎ ${t.practice?'病房會診練習':'需要及時評估的會診'}</span><h2 id="modalTitle">病人說耳朵聽不清楚。</h2><div class="dialogue">${esc(p.ward)}護理師：「${esc(p.name)}說耳朵聽不清楚，目前狀況穩定，想請 ENT 幫忙評估。」</div><div class="ng-phone-questions">${CONSULT_PHONE.map(q=>`<div><button class="choice-button" data-consult-question="${q.id}" ${t.asked.includes(q.id)?'disabled':''}><span>${t.asked.includes(q.id)?'✓':'？'}</span><span>${q.text}</span></button>${t.asked.includes(q.id)?`<p class="ng-phone-answer">護理師：「${esc(q.id==='side'?p.sideText+'。':p.onset)}」</p>`:''}</div>`).join('')}</div><p class="ng-phone-progress">已問 ${t.asked.length} / 2 項</p><button id="consultArrange" class="primary-button" ${consultReady(t)?'':'disabled'}>請原病房聯絡聽力室，儘速安排聽檢 →</button><button id="consultDismiss" class="secondary-button">只聽電話就說是耳屎，改天再說</button><button id="consultPhoneLater" class="text-button">保留來電，稍後繼續</button>`,{kind:'call'});
  const later=()=>{if(S.morning?.active)S.morning.focus=t.priorFocus;delete t.priorFocus;closeModal();};$('closeModal').onclick=later;$('consultPhoneLater').onclick=later;
  document.querySelectorAll('[data-consult-question]').forEach(b=>b.onclick=()=>{if(consultAction(t,'question',b.dataset.consultQuestion)==='asked')openConsultPhone(call);});
  $('consultDismiss').onclick=()=>{if(!t.practice)recordMistake();reply('先把目前狀況問清楚。','目前還沒有檢查結果，先確認發作時間與側別，再接上聽力檢查與評估。',()=>openConsultPhone(call),'回到這通電話');};
  $('consultArrange').onclick=()=>{if(consultAction(t,'arrange')!=='testing')return;if(call)removeCall(call.id);S.accepted=!t.practice;S.activeDest='g2';S.clinicNurseAway=true;plog('已請 '+p.ward+' 聯絡聽力室，安排 '+p.name+' 的聽力檢查。');scheduleAudiology(t);reply('原病房已聯絡聽力室。','先回 2G 初診間。聽力檢查完成後，聽力師會打電話通知病人在外面等候。\n\n這通會診還沒完成，檢查與後續進度會保留。',()=>walkToClinicSpot('desk'),'回工作桌等聽力室來電');};
}
function consultPatientStrip(t){return`<div class="consult-patient-strip"><b>${esc(t.patient.name)}</b><span>${t.patient.age} 歲 · ${esc(t.patient.ward)}</span><span>主訴：${t.patient.sideText}聽不清楚</span></div>`;}
function consultReport(t){return`<div class="consult-report"><div class="audiogram-card">${consultAudiogram(t)}<p>○ 右耳氣導　× 左耳氣導　[／] 骨導${t.branch==='sshl'?'　虛線：既往聽檢':''}</p></div><div class="consult-report-notes"><b>線上聽力報告 · 虛構資料</b><p>${t.branch==='sshl'?t.patient.sideText+'氣、骨導閾值一起下降，與既往聽檢有明顯差異。':'本次雙耳純音聽閾在正常範圍。病人仍覺得耳朵悶，接著比對耳鏡檢查。'}</p><small>圖中呈現 500、1000、2000、4000 Hz，為本題簡化聽檢。</small></div></div>`;}
function renderConsult(){
  const t=currentConsult();if(!t)return;const p=t.patient;let body='',title=consultStageText(t);
  if(['testing','results-ready'].includes(t.stage)){body=`<div class="consult-waiting"><span>◷</span><h3>${t.stage==='testing'?'聽力檢查進行中':'聽力室正在聯絡初診間'}</h3><p>聽力圖會上傳系統，等聽力室來電通知後，在電腦看報告並叫病人進來。</p></div><button id="consultWait" class="primary-button">回到診間，等候通知 →</button>`;}
  else if(t.stage==='call-patient'){title='在電腦看聽力圖，再叫病人進來。';body=`${consultReport(t)}<div class="dialogue">線上聽力圖已開啟，${esc(p.name)}在外面等。看完報告，按姓名叫病人進診間。</div><div class="tube-name-options">${t.names.map(n=>`<button data-consult-call="${esc(n)}">請${esc(n)}進診間 →</button>`).join('')}</div>`;}
  else if(t.stage==='review'){title='先把聽力圖與耳鏡發現放在一起看。';body=`<p class="small-note">已在電腦查看這次聽力圖。<button id="consultRecords" class="text-button">回電腦重看報告 →</button></p>${t.otoscopy?consultOtoscopy(t):'<button class="primary-button" data-consult-action="otoscopy">拿起耳鏡，檢查雙耳 →</button>'}${t.otoscopy?`<div class="dialogue">${t.branch==='sshl'?'雙耳耳道與鼓膜可見，沒有明顯耳垢阻塞。再比對發作時間與聽力檢查。':'兩側可見大片耳垢，仍留有部分通道。這次聽力圖正常，病人描述的耳悶也要接著確認。'}</div>${consultDiagnosticChoices(t)}`:''}`;}
  else if(t.stage==='history'){title='確實有聽損，再把病史問完整。';body=`<div class="consult-history">${CONSULT_HISTORY.map(q=>`<div><button class="choice-button" data-consult-history="${q.id}" ${t.history.includes(q.id)?'disabled':''}><span>${t.history.includes(q.id)?'✓':'？'}</span><span>${q.text}</span></button>${t.history.includes(q.id)?`<p class="ng-phone-answer">病人：「${esc(p[q.id])}」</p>`:''}</div>`).join('')}</div><button class="primary-button" data-consult-action="history-done" ${t.history.length<3?'disabled':''}>整理病史，說明接下來的評估 →</button>`;}
  else if(t.stage==='plan'){title='把治療評估與一週後聽檢交代清楚。';body=`<div class="dialogue">已確認發作時間、過去發作與慢性病史。與主治／學長確認後，向病人說明下列安排及利弊。${p.ward.startsWith('8G')?'這位有糖尿病，治療評估也要考量血糖與既有用藥。':''}</div><div class="consult-plan">${CONSULT_PLAN.map(q=>`<button class="choice-button ${t.plan.includes(q.id)?'consult-checked':''}" data-consult-plan="${q.id}" ${t.plan.includes(q.id)?'disabled':''}><span>${t.plan.includes(q.id)?'✓':'○'}</span><span>${q.text}</span></button>`).join('')}</div><p class="small-note">本題的一週後聽檢是個別追蹤安排；耳內注射依病況與治療反應評估。其餘檢查與治療以簡化劇情呈現。</p><button class="primary-button" data-consult-action="explain" ${t.plan.length<3?'disabled':''}>確認病人了解，完成說明 →</button>`;}
  else if(t.stage==='steroid-review'){title='全身類固醇治療前，先做什麼？';body=`<div class="dialogue">先和病人確認相關病史、目前用藥及治療的可能風險，再完成本次治療評估。</div><div class="consult-plan">${CONSULT_STEROID.map(q=>{const done=q.id==='counsel'?t.steroidCounselled:q.id==='med-history'?t.medHistory:false;return`<button class="choice-button" data-consult-steroid="${q.id}" ${done?'disabled':''}><span>${done?'✓':'○'}</span><span>${q.id==='give'&&t.medHistory&&t.steroidCounselled?'確認病史與說明，完成治療評估':q.text}</span></button>`;}).join('')}</div>${t.medHistory?'<p class="ng-phone-answer">本題病人與用藥紀錄確認：目前未使用抗凝血劑，沒有已知腸胃道出血病史。相關慢性病與既有用藥也已一併核對。</p>':''}${t.steroidCounselled?'<p class="ng-phone-answer">已說明可能有腸胃道不適、出血等副作用，風險須依個人病史及用藥評估；病人了解後再討論治療。</p>':''}`;}
  else if(t.stage==='clean'){title='這次的耳鏡視野，需要雙耳大掃除。';body=`<p class="modal-copy">按住耳垢區塊，讓兩側視野慢慢清楚。清理進度會保留。</p>${consultOtoscopy(t,{interactive:true})}<div class="consult-clean-progress" role="status">${t.cleaned.length} / 4 處已清理</div><p class="small-note">Tab 選取區塊後按 Enter 也能清理；此處為遊戲化的視野整理。</p>`;}
  else if(t.stage==='recheck'){title='清完了，再看一次、也再問一次。';body=`${consultOtoscopy(t)}<div class="consult-plan"><button class="choice-button" data-consult-recheck="ears" ${t.rechecked.includes('ears')?'disabled':''}>${t.rechecked.includes('ears')?'✓':'○'} 再看雙耳耳道與鼓膜</button>${t.rechecked.includes('ears')?'<p class="ng-phone-answer">本題雙耳視野清楚，鼓膜可見，沒有發現其他明顯異常。</p>':''}<button class="choice-button" data-consult-recheck="feeling" ${t.rechecked.includes('feeling')?'disabled':''}>${t.rechecked.includes('feeling')?'✓':'○'} 詢問清理後耳悶的感受</button>${t.rechecked.includes('feeling')?'<p class="ng-phone-answer">病人：「現在比較不悶了。」<br>你說明：這次聽力圖在正常範圍，若仍有或再次出現聽力變化，要再回報評估。</p>':''}</div><button class="primary-button" data-consult-action="explain" ${t.rechecked.length<2?'disabled':''}>說明檢查結果與後續安排 →</button>`;}
  else if(t.stage==='report'){title='回覆 '+p.ward+'，收好這份會診。';body=`<div class="consult-summary"><b>本次處理摘要</b><p>${t.branch==='sshl'?'已比對聽檢與耳鏡、補齊發作與病史；完成類固醇治療及耳內注射的評估說明，安排本題一週後聽檢。':'本次聽力圖正常；已清理雙耳耳垢、重看耳道與鼓膜、確認耳悶感受，完成後續說明。'}</p></div><button class="primary-button" id="consultReport">回覆原病房，完成會診紀錄 ✓</button>`;}
  modal(`${topLine('2G 初診間 · 聽力會診')}<span class="modal-tag">${t.practice?'自由練習':'病房會診'}</span><h2 id="modalTitle">${esc(title)}</h2>${consultPatientStrip(t)}${body}<button id="consultLater" class="secondary-button">先離開，進度保留</button>`,{kind:'consult',wide:true});
  $('consultLater').onclick=closeModal;if($('consultRecords'))$('consultRecords').onclick=()=>walkToClinicSpot('desk');if($('consultWait'))$('consultWait').onclick=()=>{closeModal();ringAudiology();};
  document.querySelectorAll('[data-consult-call]').forEach(b=>b.onclick=()=>{const r=consultAction(t,'call-patient',b.dataset.consultCall);if(r==='wrong-name'){if(!t.practice)recordMistake();reply('再核對一下姓名。','聽力師通知的病人是 '+p.name+'，報告與病人要對上。',renderConsult,'回工作桌叫人');return;}if(r==='called')reply(p.name+'，請進。','病人走進來，坐到診療椅。先一起看這次的聽力圖，再比對耳鏡檢查。',()=>walkToClinicSpot('patient'),'到診療椅旁');});
  document.querySelectorAll('[data-consult-diagnosis]').forEach(b=>b.onclick=()=>{const r=consultAction(t,'diagnosis',b.dataset.consultDiagnosis);if(r==='wrong-diagnosis'){if(!t.practice)recordMistake();reply('再比對一次。','把這次聽力圖、耳鏡發現與發作經過放在一起判斷。',renderConsult,'回到檢查資料');}else if(r==='diagnosed')renderConsult();});
  for(const [attr,action] of [['history','history'],['plan','plan'],['recheck','recheck']])document.querySelectorAll('[data-consult-'+attr+']').forEach(b=>b.onclick=()=>{consultAction(t,action,b.dataset['consult'+attr[0].toUpperCase()+attr.slice(1)]);renderConsult();});
  document.querySelectorAll('[data-consult-steroid]').forEach(b=>b.onclick=()=>{const result=consultAction(t,'steroid',b.dataset.consultSteroid);if(result==='premature'){if(!t.practice)recordMistake();reply('先把病史與說明補齊。','問清相關病史、抗凝血劑等既有用藥，並說明可能副作用後，再完成治療評估。',renderConsult,'回到治療說明');}else if(result!=='blocked')renderConsult();});
  document.querySelectorAll('[data-consult-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.consultAction,r=consultAction(t,action);if(r==='blocked')return;if(action==='explain'){reply('結果與後續安排已說明。','最後回工作桌，回覆 '+p.ward+' 並完成會診紀錄。',()=>walkToClinicSpot('desk'),'回工作桌回覆病房');}else renderConsult();});
  bindConsultCleaning(t);if($('consultReport'))$('consultReport').onclick=()=>{if(consultAction(t,'report')!=='done')return;const text=p.ward+'護理師：「收到，後續安排我們接上。」'+(t.branch==='wax'?'\n\n你心想：今天的雙耳大掃除，完成。':'\n\n這一位的治療評估與追蹤，已經接好了。');if(t.practice){reply('聽力會診練習完成。',text+'\n\n自由練習不計分。',closeModal,'繼續逛診間');renderHUD();}else finishCase(text);};
}
function consultDiagnosticChoices(t){return`<div class="choice-list">${shuffledOptions([{id:'sshl',text:'依這次檢查與發作經過，接續 sudden 的問診與治療評估'},{id:'wax',text:'本次聽力圖正常，先處理耳垢，再確認耳悶感受'}],'consult-diagnosis').map(o=>`<button class="choice-button" data-consult-diagnosis="${o.id}">${o.text} →</button>`).join('')}</div>`;}
function bindConsultCleaning(t){document.querySelectorAll('[data-consult-clean]').forEach(b=>{let timer;const clear=()=>{clearTimeout(timer);b.classList.remove('holding');};const finish=()=>{clear();if(consultAction(t,'clean',b.dataset.consultClean)==='cleaned')renderConsult();};b.onpointerdown=e=>{b.setPointerCapture(e.pointerId);b.classList.add('holding');timer=setTimeout(finish,500);};b.onpointerup=b.onpointercancel=clear;b.onclick=e=>{if(e.detail===0)finish();};});}
function ensureNG(){return S.wardNG??=createWardNG((S.run?.seed||'ENT')+'|'+(S.run?.team||''));}
function currentNG(){const t=S.wardNG;return t&&t.stage!=='done'&&(S.explore&&t.practice||!S.explore&&S.accepted&&phase().case==='ng')?t:null;}
function ngSummary(task){const p=task.patient;return`<div class="ng-consult-sheet"><span>線上會診摘要 · NG 放置困難</span><h3>${esc(p.name)}<small>${p.age} 歲 · ${esc(p.ward)}</small></h3><p>目前狀況穩定 · 本次會診安排在 2G 初診間</p><dl><dt>先前嘗試</dt><dd>${task.asked.includes('attempt')?esc(p.attempt):'尚未詢問'}</dd><dt>頭頸癌病史</dt><dd>${task.asked.includes('history')?esc(p.history):'尚未詢問'}</dd></dl><small>虛構病人與劇情資料</small></div>`;}
function openNGPhone(call){
  const task=ensureNG();if(task.stage!=='phone')return;const p=task.patient;
  if(task.priorFocus===undefined)task.priorFocus=S.morning?.focus||'call';if(S.morning?.active)S.morning.focus='call';
  const questions=shuffledOptions(NG_QUESTIONS,'ng-questions');
  modal(`${topLine(ngSource(task))}<span class="modal-tag">☎ ${task.practice?'會診練習':'病房會診'}</span><h2 id="modalTitle">醫師，NG 放不進去。</h2><div class="dialogue"><small>電話那一端</small>${esc(p.ward)}護理師：「${task.deferrals?'醫師，又是我們，':'ENT 醫師你好，'}${esc(p.name)}的 NG 放不進去，目前狀況穩定，想請你協助。」</div><div class="ng-phone-questions">${questions.map(q=>`<div><button class="choice-button" data-ng-question="${q.id}" ${task.asked.includes(q.id)?'disabled':''}><span>${task.asked.includes(q.id)?'✓':'？'}</span><span>${esc(q.text)}</span></button>${task.asked.includes(q.id)?`<p class="ng-phone-answer">護理師：「${esc(p[q.id])}」</p>`:''}</div>`).join('')}</div><p class="ng-phone-progress" role="status">已問 ${task.asked.length} / 2 項</p><button id="ngArrange" class="primary-button" ${ngReady(task)?'':'disabled'}>請病房安排病人到 2G 初診間 →</button><button id="ngDefer" class="secondary-button">什麼都不問，叫當科自己再試試看</button><button id="ngPhoneLater" class="text-button">保留來電，稍後繼續</button>`,{kind:'call'});
  const later=()=>{if(S.morning?.active)S.morning.focus=task.priorFocus;delete task.priorFocus;closeModal();};$('ngPhoneLater').onclick=later;$('closeModal').onclick=later;
  document.querySelectorAll('[data-ng-question]').forEach(b=>b.onclick=()=>{if(ngAction(task,b.dataset.ngQuestion)==='asked')openNGPhone(call);});
  $('ngArrange').onclick=()=>{if(ngAction(task,'arrange')!=='arranged')return;if(call)removeCall(call.id);S.accepted=!task.practice;S.activeDest='g2';S.clinicNurseAway=true;plog(p.ward+'會診：已詢問先前嘗試與頭頸癌病史，安排到 2G。');reply('病房已安排病人下來。',p.ward+'護理師：「好，病人下去，會診紀錄與病歷在電腦可以看。」\n\n'+p.name+'抵達 2G 初診間。到診療椅旁，接續評估。',()=>walkToClinicSpot('patient'),'到診療椅旁');};
  $('ngDefer').onclick=()=>{if(ngAction(task,'defer')!=='recall')return;if(!task.practice)recordMistake();if(call)removeCall(call.id);if(S.morning?.active)S.morning.focus=task.priorFocus;delete task.priorFocus;plog('未詢問病況，請 '+p.ward+' 自行再試；會診仍未完成。');reply('你：「請你們當科再試試看。」','你把電話掛了。\n\n過了一下，'+p.ward+'的分機又打來。護理師：「醫師，我們還是需要你幫忙評估……」',task.practice?()=>openNGPhone():()=>{closeModal();schedule(()=>queueCall({...call}),2500);},task.practice?'接聽再次來電':'回到手邊工作');};
}
function renderNGPatient(){
  const task=currentNG();if(!task||!['patient','confirm'].includes(task.stage))return;
  const assess=task.stage==='patient',options=shuffledOptions(assess?[{text:'核對姓名、會診需求與先前經過，再評估放置困難',good:true},{text:'不看病史，照剛才失敗的方式一直重試'}]:[{text:'核對院內位置確認紀錄，再安排後續使用與交接',good:true},{text:'看起來放進去了，就直接交代可以使用'}],'ng-'+task.stage);
  modal(`${topLine('2G 初診間 · 病房會診')}<span class="modal-tag">${task.practice?'自由練習':'病房會診'} · ${assess?'到診評估':'處理後確認'}</span><h2 id="modalTitle">${assess?'病人下來了，先把資料對起來。':'處理後，還要確認與交接。'}</h2>${ngSummary(task)}<div class="dialogue">${assess?'病人已到診，會診紀錄與病歷可在電腦查看。'+(task.patient.headNeck?'這位有頭頸癌治療病史，先了解相關紀錄，再決定合適的協助與支援。':'先核對這次會診需求與先前放置經過。'):'本劇情已依評估完成放置協助。接著核對位置確認紀錄，再回覆原病房。'}</div>${choiceList(options)}<button id="ngPatientLater" class="secondary-button">先離開，會診進度保留</button>`,{kind:'case'});
  $('ngPatientLater').onclick=closeModal;bindChoices(i=>{if(!options[i].good){if(!task.practice)recordMistake();reply('再確認一下',assess?'先看病人與已知病史，重新評估困難和需要的支援。':'不能只憑看起來放進去，就當作位置確認已完成。',renderNGPatient,'回到這位病人');return;}
    if(assess){ngAction(task,'assess');reply('會診資料已核對。','病人身分、需求、先前嘗試與相關病史都確認了。\n\n後續協助先以簡化劇情呈現，再接位置確認與交接。',renderNGPatient,'接續處理後確認');}
    else if(ngAction(task,'confirm')==='confirmed'){reply('位置確認紀錄已核對。','接著回工作桌，回覆 '+task.patient.ward+'，把這次處理結果與後續照護安排記錄好。',()=>walkToClinicSpot('desk'),'回工作桌，回覆原病房');}
  });
}
function renderNGReport(){
  const task=currentNG();if(!task||task.stage!=='report')return;
  modal(`${topLine('2G 工作桌 · 會診回覆')}<span class="modal-tag">最後交接</span><h2 id="modalTitle">回覆 ${esc(task.patient.ward)}。</h2>${ngSummary(task)}<div class="dialogue">這位的評估、處理結果與院內位置確認紀錄都整理好了。回覆原病房，交代後續照護與回報方式，再完成會診紀錄。</div><button id="ngReport" class="primary-button">回覆原病房，完成會診紀錄 ✓</button><button id="ngReportLater" class="secondary-button">稍後再回覆</button>`,{kind:'case'});
  $('ngReportLater').onclick=closeModal;$('ngReport').onclick=()=>{if(ngAction(task,'report')!=='done')return;plog('已回覆 '+task.patient.ward+'，完成 '+task.patient.name+' 的 NG 會診紀錄。');if(task.practice){reply('這件會診，收好尾了。','問清先前嘗試與頭頸癌病史、安排到診、評估確認，再回覆原病房。\n\n自由練習完成，不計分。',closeModal,'繼續逛診間');renderHUD();return;}finishCase(task.patient.ward+'護理師：「收到，後續照護安排我們接上。」\n\n你心想：電話掛下去的這一刻，先不要再響。');};
}
function ensureWardCall(id=phase().id){const p=S.run.phases.find(p=>p.id===id),base=p?.case||id;return S.wardCalls[id]??=createNightWardCall(base,(S.run?.seed||'ENT')+'|'+(S.run?.team||'')+(id===base?'':'|'+id),{instanceId:id,requestId:p?.requestId});}
function currentWardCall(){return!S.explore&&S.accepted&&NIGHT_WARD_IDS.includes(phase().case)?ensureWardCall():null;}
function renderWardConsent(message=''){
  const task=currentWardCall();if(task?.id!=='wardConsent'||task.done||!nearWorkSpot(consentSpot(task),'f7'))return;
  modal(`${topLine('7F 護理站 · '+(['tablet','mrn','sign'].includes(task.consent.stage)?'平板':'可晴護理師'))}<span class="modal-tag">同意書 · ${task.step+1} / ${CONSENT_LABELS.length}</span><h2 id="modalTitle">${esc(CONSENT_LABELS[task.step])}</h2>${consentHTML(task,message)}`,{kind:'ward-consent',wide:true});
  const act=(action,value)=>{
    if(!nearWorkSpot(consentSpot(task),'f7'))return;const before=consentSpot(task),r=consentAction(task,action,value);
    if(!r.ok){if(r.penalty)recordMistake();renderWardConsent(r.message||'先完成目前這一步。');return;}
    if(r.completed){spendShiftTime(S,4);finishCase(r.message);return;}
    if(consentSpot(task)!==before){closeModal();renderHUD();toast(consentStageText(task));return;}
    renderWardConsent();renderHUD();
  };
  if($('consentVerifyChoices')){const options=shuffledOptions(task.steps[0].options,'consent-verify');$('consentVerifyChoices').innerHTML=choiceList(options);bindChoices(i=>act('verify',options[i]));}
  document.querySelectorAll('[data-consent-action]').forEach(b=>b.onclick=()=>act(b.dataset.consentAction));
  const input=$('consentMRN');if(input){input.oninput=()=>{input.value=input.value.replace(/\D/g,'').slice(0,8);consentAction(task,'input',input.value);};input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();act('lookup');}};}
  document.querySelectorAll('[data-consent-key]').forEach(b=>b.onclick=()=>{const key=b.dataset.consentKey,value=key==='清除'?'':key==='⌫'?task.consent.mrnInput.slice(0,-1):task.consent.mrnInput+key;consentAction(task,'input',value);$('consentMRN').value=task.consent.mrnInput;});
  $('consentLater').onclick=closeModal;
}
function renderConsentHUD(){
  const t=currentWardCall();if(t?.id!=='wardConsent'||t.done)return;
  $('missionIndex').textContent='病房小 call · '+(t.step+1)+' / '+CONSENT_LABELS.length;$('missionTitle').textContent=CONSENT_LABELS[t.step];$('missionDescription').textContent=consentStageText(t);$('missionDestination').textContent='7F 護理站 · '+(consentSpot(t)==='consent-tablet'?'平板':'可晴護理師');
}

function renderWardCall(){
  const task=currentWardCall();if(task?.id==='wardConsent'){renderWardConsent();return;}
  if(!task||task.done||!world.spots.some(s=>isWardComputer(S.location,S.orRoom,s.id)&&nearWorkSpot(s.id,S.location,S.orRoom)))return;
  const options=shuffledOptions(task.steps[0].options,'quick-ward');
  modal(`${topLine((S.orRoom?S.orRoom+'房':LOCATIONS[S.location].code)+' · 電腦')}<span class="modal-tag">病房小 call</span><h2 id="modalTitle">${esc(task.item)}</h2><section class="ward-call-paper"><header><b>${esc(task.patient.name)}</b><span>${esc(task.patient.bed)}</span></header>${task.surgery?`<p><b>手術：</b>${esc(task.surgery)}</p>`:''}<p>${esc(task.memo)}</p></section>${choiceList(options)}<p id="wardQuickFeedback" class="activity-feedback" role="status"></p><button id="wardCallLater" class="secondary-button">先離開，待會再處理</button>`,{kind:'ward-call',wide:true});
  bindChoices(i=>{const r=wardCallAction(task,options[i]);if(!r.ok){if(r.penalty)recordMistake();$('wardQuickFeedback').textContent=r.message||'再確認一下。';renderHUD();return;}if(r.completed){spendShiftTime(S,2);finishCase(r.message);}});$('wardCallLater').onclick=closeModal;
}
function renderWardQuickHUD(){
  const t=currentWardCall();if(!t||t.id==='wardConsent')return;
  const target=wardComputerTarget(S.location,S.orRoom);$('missionIndex').textContent='病房小 call';$('missionTitle').textContent='找電腦 · '+t.item;$('missionDescription').textContent='不用特別回病房，任意一台可操作的電腦都能處理。';$('missionDestination').textContent=target.dest==='f5'?'13／16房 · 電腦':target.dest==='g2'?'2G 初診間 · 電腦':'7F 護理站 · 電腦';
}

function renderCase(){if(phase().case==='fish'){renderFish();return;}if(NIGHT_WARD_IDS.includes(phase().case)){renderWardCall();return;}if(phase().case==='contact'){renderContact();return;}if(phase().case==='booking'){loginComputer(renderBooking);return;}if(LOCAL_OR_IDS.includes(phase().case)){ensureORProcedure();if(currentLocalOR())renderLocalOR();else renderNPX();return;}if(phase().case==='sudden'){renderConsult();return;}if(phase().case==='ng'){renderNGPatient();return;}if(TUBE_CASES.includes(phase().case)){renderTubeGame();return;}if(phase().case==='outpatientPaperwork'){openHearingGame();return;}const c=CASES[phase().case],step=c.steps[S.caseStep];if(!step)return;const options=shuffledOptions(step.options,'step'+S.caseStep);modal(`${topLine(S.location==='f5'?operatingLabel(assignedOR()):LOCATIONS[S.location].code+' · 現場事件')}<span class="modal-tag ${c.urgent?'urgent':''}">${esc(c.tag)}</span><h2 id="modalTitle">${esc(c.title)}</h2><p class="modal-copy">${esc(c.patient)}</p>${S.caseStep===0?`<div class="dialogue">${lines(c.intro)}</div>`:''}<p class="modal-copy"><b>${esc(step.ask)}</b></p>${choiceList(options)}`,{kind:'case'});bindChoices(i=>{const o=options[i];if(!o.good){recordMistake();reply('再想一下',o.reply,renderCase,'回到現場');return;}if(o.support)S.stats.support++;if(o.action==='or'){S.caseMode='or';S.activeDest='f5';reply('接上刀房團隊',o.reply+'\n流動來電：請到 '+assignedOR()+' 號，團隊在裡面等你。',()=>{closeModal();renderHUD();},'前往 '+assignedOR()+' 號刀房');return;}S.caseStep++;if(S.caseStep>=c.steps.length)finishCase(o.reply);else reply('現場回應',o.reply,renderCase);});}
function finishCase(text){const id=phase().id;if(!S.completed.includes(id)){S.completed.push(id);applyEffects(caseData(id).effect);workVitals(S);plog(`${caseData(id).title}完成 · ${eventPoints(id,S.eventErrors)} / 10 分`);buildMarkers();}if(S.morning?.printed)S.morning.firstCallDone=true;S.accepted=false;reply('這件事，收好尾了。',text+(S.morning?.active?'\n\n病房待辦仍保留；先接續診間工作，有空再回去處理。':''),S.run?.studio&&!parallelCalls(S)?showStudioResult:advance,S.run?.studio&&!parallelCalls(S)?'查看單項試玩結果':'接續今天的工作');renderHUD();}
function handover(){if(S.opening&&!S.opening.checked){showMorningCalendar();return;}if(parallelCalls(S)&&S.clock>=1890){if(S.morning?.active){reply('交班前，再把病房待辦收尾。','查房與清鼻子仍留在待辦。',()=>{S.morning.focus=roundsComplete(S.morning)?'nasal':'rounds';closeModal();syncMorning();guide();});}else showSummary();return;}if(phase().id==='morning'||parallelCalls(S)&&S.morning&&!S.morning.printed){reply('先把今天的名單印出來。',`在護理站電腦打開 patient list，準備列印今天要查房的名單。\n\n依名單自行走到每一床，確認病人現況與今日計畫。整份名單查房完成後，再帶 SMP 術後病人到 7F 檢查室清鼻子。\n\n08:30 以後，診間會打來通知門診工作，下午學長再找你進刀房；未完成的工作會留在待辦清單。`,()=>{if(!printPatientList(S.morning))return;if(S.opening)S.opening.focused=false;plog('在護理站印出 patient list，開始依名單查房。');advance();syncMorning();showPatientList();},'列印 patient list');}else if(S.morning?.active){reply('交班前，再把病房待辦收尾。','查房與清鼻子都保留在待辦清單。回去完成後，再來交班。',()=>{S.morning.focus=roundsComplete(S.morning)?'nasal':'rounds';closeModal();syncMorning();guide();},'回到病房待辦');}else showSummary();}
function closestRestSpot(){return world?.spots.filter(s=>s.restPose&&canUseDutyRoom(s,S.character)).sort((a,b)=>Math.hypot(a.x-world.position.x,a.z-world.position.z)-Math.hypot(b.x-world.position.x,b.z-world.position.z))[0];}
function selfCareTarget(){if(!S.started||S.ending)return null;const need=refreshNeeds(S);if(need==='rest'){const spot=closestRestSpot();return spot?{dest:S.location,spot:spot.id}:null;}if(need==='food')return operatingViewTarget({dest:S.location==='f7'?'f7':'g2',spot:S.location==='f7'?'nurse':'snacks'},S.orRoom);return null;}
function standForWork(){if(S.care.posture==='stand')return true;if(!endRest(S)){toast('體力還不夠，先休息到30；可以繼續接電話。');return false;}world.setPosture('stand');renderHUD();return true;}
function beginWorldRest(spot){
  if(!spot?.restPose||S.care.posture!=='stand')return;
  if(!canUseDutyRoom(spot,S.character)){reply('走錯值班室了。','這間是'+(spot.allowedCharacter==='male'?'男生':'女生')+'值班室。你的床在'+(S.character==='male'?'左邊的男生':'右邊的女生')+'值班室。',closeModal,'回到走廊');return;}
  if(S.morning?.escort==='following'){escortTravel();return;}
  const night=spot.restPose==='lie'&&(parallelCalls(S)?S.clock>=1440:phase().kind==='sleep')&&!S.explore;
  if(!beginRest(S,spot,{night}))return;closeModal();keys.clear();world.stop();world.setPosture(spot.restPose,spot);if(S.awaitingDesk&&S.location==='g2'){S.awaitingDesk=false;const c=CASES[phase().case];queueCall({id:phase().case,kind:'case',caseId:phase().case,title:c.title,source:c.source,urgent:c.urgent});}plog(spot.restPose==='lie'?'你躺到值班室的床上，開始休息。':'你坐了下來，電話還是接得到。');renderHUD();
}
