  if($('contactReadDirectory'))$('contactReadDirectory').onclick=()=>act('directory');document.querySelectorAll('[data-contact-key]').forEach(b=>b.onclick=()=>{const k=b.dataset.contactKey;act(['clear','erase'].includes(k)?k:'digit',k);});document.querySelectorAll('[data-contact-action]').forEach(b=>b.onclick=()=>act(b.dataset.contactAction));document.querySelectorAll('[data-contact-relay]').forEach(b=>b.onclick=()=>act('relay',b.dataset.contactRelay));$('contactPause').onclick=closeModal;
