  const finish=(support=false)=>{if(done)return;done=true;held=false;S.stats.operations++;S.stats.stability.push(support?null:Math.min(100,Math.round(goodDown/Math.max(1,totalDown)*100)));if(support){S.stats.support++;changeTemper(-5);}const text=support?'周學長：「我接這一段，你先把手放鬆。剛剛有一起配合，很好。」':'美玲：「可以喔，越來越穩了。」\n周學長：「慢慢來，先看清楚。」';plog(support?'刀房操作由學長支援收尾。':'完成刀房操作。');if(phase().kind==='case')finishCase(text);else reply(support?'團隊一起收尾':'這一段，完成了。',text,advance,'繼續今天的工作');};$('surgerySupport').onclick=()=>finish(true);
