function spotLabel(s){if(S.orRoom===13&&s.id==='operation')return'手術台 · '+(currentLocalOR()?LOCAL_PROCEDURES[currentLocalOR().kind].name:currentNPX()?'NPX biopsy':'選擇手術');const c=SIDE_ACTIVITIES[s.id];return c?(S.side.completed.includes(activityKey(S.location,S.orRoom,s.id))?c.done:s.label):s.label;}
function buildMarkers(){$('roomLabels').innerHTML='';labelNodes.clear();for(const item of world.labels){const label=document.createElement('span');label.className='ward-label '+item.kind;label.textContent=item.text;if(item.detail){label.title=item.detail;label.setAttribute('aria-label',item.text+'，'+item.detail);}if(item.columns)label.style.maxWidth=`${item.columns}em`;$('roomLabels').append(label);labelNodes.set(item.id,label);}$('markers').innerHTML='';markerNodes.clear();for(const s of world.spots){const b=document.createElement('button');b.className='world-marker';const label=spotLabel(s);b.innerHTML=`<span class="marker-dot"></span>${esc(label)}`;b.setAttribute('aria-label','走近'+label);b.onclick=()=>{if(S.mode!=='walk')return;if(S.care.posture!=='stand'&&!standForWork())return;const d=world.distanceToSpot(s);if(d<interactionRange(s))interact(s);else{selectedObject={id:s.id,location:S.location,orRoom:S.orRoom};if(!world.walkToSpot(s.id)){selectedObject=null;toast('換一個位置走近看看。');}}};$('markers').append(b);markerNodes.set(s.id,b);}}
