  $('interactButton').hidden=!near||S.mode!=='walk'||!S.started||S.care.posture!=='stand';$('walkHint').hidden=!!near||!S.started||!!S.orRoom||S.care.posture!=='stand';if(near)$('interactLabel').textContent=spotLabel(near);
